[
  {
    "question": "Which statement correctly distinguishes a database instance from a database schema?",
    "options": {
      "A": "The schema defines the logical structure of the database, while the instance is the current data stored at a point in time.",
      "B": "The instance specifies the tables and columns, whereas the schema contains the actual rows of data.",
      "C": "Both schema and instance refer to the same concept; they are interchangeable terms.",
      "D": "The schema stores user privileges, while the instance records only system logs."
    },
    "correct_answer": "A",
    "explanation": "According to the syllabus, a schema describes the logical design (tables, attributes, constraints), whereas an instance is the actual set of data present at a particular moment.",
    "difficulty": "Medium"
  },
  {
    "question": "Physical data independence protects applications from changes in which of the following?",
    "options": {
      "A": "Logical table relationships such as foreign keys",
      "B": "User-defined views and query formulations",
      "C": "Storage structures like file organization and indexing methods",
      "D": "Business rules enforced by CHECK constraints"
    },
    "correct_answer": "C",
    "explanation": "Physical data independence means that modifications to the internal storage (e.g., file formats, indexing) do not affect the external schema or application programs.",
    "difficulty": "Medium"
  },
  {
    "question": "In SQL, which type of constraint is most appropriate for enforcing a rule that a column’s value must satisfy a specific condition (e.g., salary > 0)?",
    "options": {
      "A": "PRIMARY KEY",
      "B": "UNIQUE",
      "C": "CHECK",
      "D": "FOREIGN KEY"
    },
    "correct_answer": "C",
    "explanation": "A CHECK constraint allows the DBMS to enforce arbitrary predicates on column values, such as ensuring salaries are positive.",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following items is typically NOT stored in the DBMS system catalog?",
    "options": {
      "A": "Definitions of tables, columns, and indexes",
      "B": "User authentication passwords in plain text",
      "C": "Metadata about view definitions",
      "D": "Information about stored procedures"
    },
    "correct_answer": "B",
    "explanation": "The system catalog holds metadata about database objects; it never stores user passwords in plain text for security reasons.",
    "difficulty": "Medium"
  },
  {
    "question": "How does the transaction log contribute to the durability property of ACID?",
    "options": {
      "A": "It locks rows to prevent concurrent updates.",
      "B": "It records all modifications so they can be replayed after a crash.",
      "C": "It validates foreign key relationships before commit.",
      "D": "It optimizes query execution plans."
    },
    "correct_answer": "B",
    "explanation": "Durability requires that once a transaction commits, its effects survive failures; the transaction log stores the changes so they can be recovered after a crash.",
    "difficulty": "Medium"
  }
]
